let editMessageIndex=null;
let editMessageTimer=null;
let editMessageMoved=false;
function openEditMessage(index){
 const msg=chatFor(activeChat)[index];
 if(!msg || msg.from!=="me")return;
 editMessageIndex=index;
 document.getElementById("editMessageText").value=msg.text||"";
 document.getElementById("editMessageModal").classList.remove("hidden");
 document.getElementById("editMessageText").focus();
}
function closeEditMessage(){
 editMessageIndex=null;
 document.getElementById("editMessageModal")?.classList.add("hidden");
}
function setupMessageEditing(){
 const area=document.getElementById("messages");
 if(!area || area.dataset.editReady)return;
 area.dataset.editReady="1";
 area.addEventListener("pointerdown",e=>{
   const msg=e.target.closest("[data-message-index]");
   if(!msg || msg.dataset.messageFrom!=="me")return;
   editMessageMoved=false;
   clearTimeout(editMessageTimer);
   const index=Number(msg.dataset.messageIndex);
   editMessageTimer=setTimeout(()=>{if(!editMessageMoved)openEditMessage(index)},550);
 });
 area.addEventListener("pointermove",()=>{editMessageMoved=true;clearTimeout(editMessageTimer)});
 area.addEventListener("pointerup",()=>clearTimeout(editMessageTimer));
 area.addEventListener("pointercancel",()=>clearTimeout(editMessageTimer));
 area.addEventListener("contextmenu",e=>{
   const msg=e.target.closest("[data-message-index]");
   if(msg && msg.dataset.messageFrom==="me"){
     e.preventDefault();
     openEditMessage(Number(msg.dataset.messageIndex));
   }
 });
}

function autoReply(text){
 const p=profile(activeChat),lower=text.toLowerCase();
 let rule=p.autoReply.find(r=>r.keywords.some(k=>lower.includes(k.toLowerCase())));
 const allReplies=p.autoReply.map(r=>r.reply);
 const reply=rule?.reply || allReplies[Math.floor(Math.random()*allReplies.length)];

 // Simulated reply delay: randomly wait 5–20 minutes.
 // This is intentionally a simulation; the timer runs while the page is open.
 const delayMs=(5*60*1000)+Math.floor(Math.random()*(15*60*1000+1));
 const targetId=activeChat;
 setTimeout(()=>{
   const target=profile(targetId);
   if(!target)return;
   chatFor(targetId).push({from:"them",text:reply,time:time()});
   addNotif(`${target.name} replied to your message`);
   save();
   if(activeChat===targetId){
     document.getElementById("typing").classList.add("hidden");
     renderMessages();
   }
   renderChats();
 },delayMs);
}
function sendMessage(){
 const input=document.getElementById("messageInput"),text=input.value.trim();if(!text||!activeChat)return;
 chatFor(activeChat).push({from:"me",text,time:time()});input.value="";save();renderMessages();renderChats();autoReply(text);
}
